    #[test]
    fn default_settings_fov_matches_camera_default_fov() {
        // Wiring guard for the settings-driven FOV (S04-T04): GameApp::new
        // now copies fov_degrees.to_radians() onto the camera at startup,
        // so the default settings FOV must equal Camera::new's hardcoded
        // 75-degree default — the source-of-truth swap stays neutral.
        let camera = Camera::new(Vec3::ZERO);
        assert_eq!(
            camera.fov_y_radians,
            Settings::default().fov_degrees.to_radians()
        );
    }

    #[test]
    fn gameplay_keys_route_through_the_loaded_keybind_map_press_and_release() {
        let mut input = InputState::default();
        let binds = Keybinds::default();
        let presses = [
            (KeyCode::KeyW, "forward"),
            (KeyCode::KeyS, "backward"),
            (KeyCode::KeyA, "left"),
            (KeyCode::KeyD, "right"),
            (KeyCode::Space, "jump_or_up"),
            (KeyCode::ShiftLeft, "crouch_or_down"),
            (KeyCode::ControlLeft, "sprint"),
        ];
        for (code, name) in presses {
            assert!(
                apply_gameplay_key(&mut input, &binds, code, true),
                "{name} press routes through the map"
            );
        }
        assert!(
            input.forward
                && input.backward
                && input.left
                && input.right
                && input.jump_or_up
                && input.crouch_or_down
                && input.sprint
        );
        // releases clear the same flags through the same map — both
        // transitions route identically (pre-rebind semantics preserved).
        for (code, name) in presses {
            assert!(
                apply_gameplay_key(&mut input, &binds, code, false),
                "{name} release routes through the map"
            );
        }
        assert!(
            !input.forward
                && !input.backward
                && !input.left
                && !input.right
                && !input.jump_or_up
                && !input.crouch_or_down
                && !input.sprint
        );
    }

    #[test]
    fn rebound_keys_take_effect_and_the_replaced_key_goes_dead() {
        // same rebind as the compose test: jump_or_up from Space to ArrowUp
        let binds = opencraft_keybinds_jump_arrow_up();
        let mut input = InputState::default();
        assert!(apply_gameplay_key(
            &mut input,
            &binds,
            KeyCode::ArrowUp,
            true
        ));
        assert!(input.jump_or_up, "the new key jumps");
        // the replaced key is unbound now — Space no longer jumps
        assert!(!apply_gameplay_key(
            &mut input,
            &binds,
            KeyCode::Space,
            true
        ));
        // an unbound press must not disturb the flag either way: the
        // ArrowUp press keeps it set, and no stick/clear happens from Space
        assert!(
            input.jump_or_up,
            "an unbound key press must not clear the flag"
        );
        // release through the new key clears the flag
        assert!(apply_gameplay_key(
            &mut input,
            &binds,
            KeyCode::ArrowUp,
            false
        ));
        assert!(!input.jump_or_up);
        // the old key's release is unbound too and must not resurrect it
        assert!(!apply_gameplay_key(
            &mut input,
            &binds,
            KeyCode::Space,
            false
        ));
        assert!(!input.jump_or_up);
    }

    #[test]
    fn only_the_bound_crouch_and_sprint_keys_trigger() {
        // intentional narrowing (documented on Keybinds in src/settings):
        // rebindable bindings are single keys, so ShiftRight/ControlRight no
        // longer crouch/sprint the way the old hardcoded pairs did.
        let binds = Keybinds::default();
        let mut input = InputState::default();
        assert!(!apply_gameplay_key(
            &mut input,
            &binds,
            KeyCode::ShiftRight,
            true
        ));
        assert!(!apply_gameplay_key(
            &mut input,
            &binds,
            KeyCode::ControlRight,
            true
        ));
        assert_eq!(
            format!("{:?}", input),
            format!("{:?}", InputState::default()),
            "unbound siblings must not touch InputState"
        );
    }

    #[test]
    fn non_gameplay_keys_report_not_bound_and_leave_input_untouched() {
        let binds = Keybinds::default();
        let mut input = InputState::default();
        for code in [
            KeyCode::KeyQ,
            KeyCode::KeyZ,
            KeyCode::KeyF,
            KeyCode::F5,
            KeyCode::Escape,
        ] {
            assert!(
                !apply_gameplay_key(&mut input, &binds, code, true),
                "{code:?} is not a gameplay bind"
            );
        }
        assert_eq!(
            format!("{:?}", input),
            format!("{:?}", InputState::default())
        );
    }

    #[test]
    fn duplicate_bindings_in_a_hand_edited_file_resolve_first_match() {
        // load does not deduplicate; first-match priority in Keybinds
        // declaration order keeps routing deterministic instead of
        // last-write-wins per flag.
        let binds = Keybinds {
            backward: KeyCode::KeyW, // collides with forward
            ..Keybinds::default()
        };
        let mut input = InputState::default();
        assert!(apply_gameplay_key(&mut input, &binds, KeyCode::KeyW, true));
        assert!(input.forward, "forward is declared first and wins");
        assert!(!input.backward, "the duplicate loser stays clear");
    }

    #[test]
    fn cli_bypass_condition_is_exactly_the_three_flag_disjunction() {
        // Bare launch: no CLI world intent — the main menu owns startup.
        assert!(!cli_has_world_intent(&CliConfig::parse_args(
            Vec::<String>::new()
        )));
        // The default save path alone is NOT an intent (byte-identical default).
        assert!(!cli_has_world_intent(&CliConfig::parse_args([
            "--save",
            "saves/default.mcvx"
        ])));
        // Each flag alone forces the direct-launch bypass into gameplay.
        assert!(cli_has_world_intent(&CliConfig::parse_args(["--new"])));
        assert!(cli_has_world_intent(&CliConfig::parse_args([
            "--new-world"
        ])));
        assert!(cli_has_world_intent(&CliConfig::parse_args([
            "--seed", "7"
        ])));
        assert!(cli_has_world_intent(&CliConfig::parse_args([
            "--save",
            "other.mcvx"
        ])));
        // `--time-scale` is a test seam, NOT a world intent: a bare
        // accelerated launch still opens the main menu.
        assert!(!cli_has_world_intent(&CliConfig::parse_args([
            "--time-scale",
            "60"
        ])));
        // Mode flags are fresh-world parameters too, NOT a world intent: a
        // bare `--creative` or `--survival` still opens the main menu.
        assert!(!cli_has_world_intent(&CliConfig::parse_args([
            "--creative"
        ])));
        assert!(!cli_has_world_intent(&CliConfig::parse_args([
            "--survival"
        ])));
        let scaled = GameApp::new(
            CliConfig::parse_args(["--time-scale", "60"]),
            WorldSession::new_session(9, PathBuf::from("unused.mcvx"), DEFAULT_SEASON_LENGTH_DAYS),
        );
        assert_eq!(scaled.lifecycle.screen(), LifecycleScreen::MainMenu);
        assert_eq!(
            scaled.time_scale, 60.0,
            "the CLI scale reaches the app but never forces gameplay"
        );
        // `--season-length` is a fresh-world parameter, NOT a world intent:
        // on its own it must not bypass the main menu (same rule as
        // `--time-scale`).
        assert!(!cli_has_world_intent(&CliConfig::parse_args([
            "--season-length",
            "4"
        ])));
        // Every flag together still bypasses (the smoke scripts' launches).
        assert!(cli_has_world_intent(&CliConfig::parse_args([
            "--new",
            "--seed",
            "999",
            "--save",
            "custom.mcvx"
        ])));
    }

    #[test]
    fn scripted_demo_flags_are_launch_switches_and_never_world_intents() {
        // Each new scripted-demo flag alone is NOT a world intent: a bare
        // launch plus the flag still opens the main menu, exactly like a bare
        // launch. (The effect belongs to the fresh startup branch only.)
        let bare = CliConfig::parse_args(Vec::<String>::new());
        for flag in [
            "--demo-swim",
            "--demo-survival",
            "--demo-content",
            "--demo-combat",
        ] {
            let cli = CliConfig::parse_args([flag]);
            assert!(
                !cli_has_world_intent(&cli),
                "{flag} alone must not bypass the menus"
            );
            assert_eq!(cli_has_world_intent(&cli), cli_has_world_intent(&bare));
        }

        // Combined with a real world flag the intent is unchanged (the world
        // flag is still what grants direct gameplay entry).
        for flag in [
            "--demo-swim",
            "--demo-survival",
            "--demo-content",
            "--demo-combat",
        ] {
            let with_new = CliConfig::parse_args(["--new", flag]);
            assert!(
                cli_has_world_intent(&with_new),
                "{flag} + --new keeps intent"
            );
        }
    }

    #[test]
    fn validate_pack_is_a_launch_switch_and_never_a_world_intent() {
        // Validation is a headless one-shot: naming a pack must not bypass the
        // menu on a normal launch, exactly like the other launch switches.
        let bare = CliConfig::parse_args(Vec::<String>::new());
        let validate = CliConfig::parse_args(["--validate-pack", "mymod-ruby"]);
        assert!(!cli_has_world_intent(&validate));
        assert_eq!(cli_has_world_intent(&validate), cli_has_world_intent(&bare));

        // A real world flag still grants intent; the validation switch is not
        // persisted or turned into a world parameter.
        let with_new = CliConfig::parse_args(["--new", "--validate-pack", "demo"]);
        assert!(cli_has_world_intent(&with_new));
        assert_eq!(with_new.validate_pack.as_deref(), Some("demo"));
    }

    #[test]
    fn main_validate_pack_short_circuit_precedes_world_startup() {
        // Validation must run before any world/session startup: no save,
        // settings file, window, or GPU work is allowed on this launch. Pin
        // the ordering in the real binary source so a later refactor cannot
        // silently move the seam behind `startup_session`.
        let source = include_str!("main.rs");
        let body = source
            .split("fn main()")
            .nth(1)
            .expect("main.rs must define fn main");
        let validate_at = body
            .find("cli.validate_pack")
            .expect("fn main must branch on cli.validate_pack");
        let lines_at = body
            .find("validate_pack_lines")
            .expect("fn main must call validate_pack_lines");
        let startup_at = body
            .find("StartupContent::load(")
            .expect("fn main must build StartupContent before starting a session");
        assert!(
            validate_at < startup_at,
            "cli.validate_pack must precede startup"
        );
        assert!(
            lines_at < startup_at,
            "validate_pack_lines must precede startup"
        );
        assert!(
            validate_at < body.find("cli.demo_ui").unwrap_or(usize::MAX),
            "validate-pack must precede the demo-ui branch"
        );
    }

    #[test]
    fn playing_frame_builds_mobs_into_the_reused_buffer() {
        // No headless test can execute the GPU render arm, so pin its shape in
        // the real binary source (M016/S08): the Playing frame must refill the
        // batch buffer retained on `GameApp` in place and hand that same
        // buffer to the renderer, never build a fresh `Vec` every frame.
        let source = include_str!("main.rs");
        let arm = source
            .split("build_mob_batch_into(")
            .nth(1)
            .and_then(|rest| rest.split("FrameView {").next())
            .expect("the Playing arm must call build_mob_batch_into");
        assert!(
            arm.contains("&mut self.mob_vertices"),
            "the Playing frame must refill the retained mob_vertices buffer in place"
        );
        assert!(
            arm.contains("&self.mob_vertices"),
            "the renderer must receive the retained mob_vertices buffer"
        );
        // Build the prohibited needle at runtime: a plain literal would match
        // itself inside this included `main.rs` source.
        let allocating = ["let mob_vertices = ", "build_mob_batch("].concat();
        assert!(
            !source.contains(&allocating),
            "the frame path must not allocate a fresh mob batch every frame"
        );
    }

