    /// Build the real generated-terrain fixture shared by the fresh combat-leg
    /// tests: the production spawn chunks, the production hostile gate, the
    /// Settle-style terrain+1 grounding, and a fresh demo. No stage is stepped.
    fn fresh_combat_fixture(seed: u32, save_path: PathBuf) -> (WorldSession, CombatDemo) {
        let mut session = WorldSession::new_session_with_mode(
            seed,
            save_path,
            DEFAULT_SEASON_LENGTH_DAYS,
            GameMode::Survival,
        );
        let spawn = WorldSession::spawn_position(seed);
        insert_generated_chunk_with_generated_face_neighbors(
            &mut session,
            IVec3::new(
                spawn.x.floor() as i32,
                spawn.y.floor() as i32,
                spawn.z.floor() as i32,
            ),
        );
        insert_generated_chunk_with_generated_face_neighbors(
            &mut session,
            IVec3::new(
                spawn.x.floor() as i32,
                (spawn.y - 4.0).floor() as i32,
                spawn.z.floor() as i32,
            ),
        );
        // Mirror the production scripted startup: the pinned quartet sits
        // inside the 16-block aggro, so hostile AI stays off until the
        // dedicated Hostile stage reopens it. Without this parity the new
        // skeleton shot seam (S08-T02) fires during Walk and leaves arrows for
        // the Shot stage's empty-list pin.
        session.set_hostile_ai_enabled(false);

        // Ground the player like the real Playing frames do during Settle: the
        // deterministic spawn is four blocks above the terrain surface, and a
        // headless leg never runs player physics. The Skeleton stage's spot
        // search requires a supported standing cell next to the player, so this
        // is fixture parity, not a gameplay change.
        let feet = terrain_height_at_seeded(spawn.x.floor() as i32, spawn.z.floor() as i32, seed)
            as f32
            + 1.0;
        session.player.position.y = feet;
        session.sync_camera();
        insert_generated_chunk_with_generated_face_neighbors(
            &mut session,
            IVec3::new(
                spawn.x.floor() as i32,
                feet.floor() as i32,
                spawn.z.floor() as i32,
            ),
        );

        let demo = CombatDemo::new(seed, true, None);
        (session, demo)
    }

    /// Step the shared fresh leg from Settle through the standard stages. When
    /// `stop_before` names a stage, the loop returns at the top of the update
    /// that would step it, leaving the demo parked on that stage.
    fn step_fresh_combat_leg(
        session: &mut WorldSession,
        demo: &mut CombatDemo,
        stop_before: Option<CombatStage>,
    ) {
        assert!(!combat_demo_step(demo, session), "settle");
        assert_eq!(demo.stage, CombatStage::Ambient, "the spawn gate settles");
        // This test pins Walk/Fight/Drops/Save; the Ambient proof has its own
        // dedicated test, and the 7-chunk demo fixture has no light grids, so
        // it could never satisfy `column_ready`.
        demo.stage = CombatStage::Spawn;
        assert!(!combat_demo_step(demo, session), "spawn");
        assert_eq!(demo.stage, CombatStage::Walk);
        for pos in demo.spawn_positions {
            insert_generated_chunk_with_generated_face_neighbors(
                session,
                IVec3::new(
                    pos.x.floor() as i32,
                    pos.y.floor() as i32,
                    pos.z.floor() as i32,
                ),
            );
        }
        let mut updates = 0;
        let mut ended = false;
        while !ended && updates < 600 {
            if stop_before == Some(demo.stage) {
                assert!(!demo.failed, "unexpected abort: {:?}", demo.digest);
                return;
            }
            updates += 1;
            session.tick_mobs(0.05, 1.0);
            if demo.stage == CombatStage::Hostile {
                // The hostile proof has its own dedicated test (and needs a lit
                // synthetic world); this helper pins the fresh
                // Walk/Fight/Drops/Shot/Save leg, so hand straight to Shot (which
                // earns the bow and arrows the save witness carries) and keep the
                // pinned `combat_demo:` digest byte-identical.
                demo.stage = CombatStage::Shot;
            }
            ended = combat_demo_step(demo, session);
        }
        assert!(
            demo.finished(),
            "the fresh leg must finish within 600 updates"
        );
        assert!(!demo.failed, "unexpected abort: {:?}", demo.digest);
    }

    /// Run a headless fresh combat leg (Settle -> Spawn -> Walk -> Shot ->
    /// Skeleton -> Creative -> Save) to completion and return the session plus
    /// its finished demo. Both save-leg tests use this so the fresh save is
    /// always produced by the production Save stage rather than hand-built wire
    /// data.
    fn run_fresh_combat_leg(seed: u32, save_path: PathBuf) -> (WorldSession, CombatDemo) {
        let (mut session, mut demo) = fresh_combat_fixture(seed, save_path);
        step_fresh_combat_leg(&mut session, &mut demo, None);
        (session, demo)
    }

    /// Run the shared fresh leg but park it on the Skeleton stage before that
    /// stage steps. The full 3x3 chunk grid around the spawn chunk is loaded so
    /// the 5.5-9.5-block spot lattice is resident for any spawn position (the
    /// plus-only coverage may miss the diagonal chunk that holds seed 1's
    /// canonical first bow cell).
    fn run_fresh_combat_leg_until_skeleton(
        seed: u32,
        save_path: PathBuf,
    ) -> (WorldSession, CombatDemo) {
        let (mut session, mut demo) = fresh_combat_fixture(seed, save_path);
        let feet = session.player.position;
        let cs = CHUNK_SIZE as i32;
        let base = IVec3::new(
            feet.x.floor() as i32,
            feet.y.floor() as i32,
            feet.z.floor() as i32,
        );
        // Five plus-shaped inserts (centre, +x, -x, +z, -z) union to the 3x3
        // chunk grid around the spawn chunk.
        for offset in [
            IVec3::ZERO,
            IVec3::new(cs, 0, 0),
            IVec3::new(-cs, 0, 0),
            IVec3::new(0, 0, cs),
            IVec3::new(0, 0, -cs),
        ] {
            insert_generated_chunk_with_generated_face_neighbors(&mut session, base + offset);
        }
        step_fresh_combat_leg(&mut session, &mut demo, Some(CombatStage::Skeleton));
        (session, demo)
    }

    /// Pre-fix this aborts at the fire proof (`observed=fired=20 player_hits=0`):
    /// a mid-fall fractional feet height floors into the empty cell above the
    /// standing cell, so the spot lattice rejects every candidate. The stage must
    /// settle the body onto the world's real block top and complete on the real
    /// generated-terrain fixture.
    #[test]
    fn combat_skeleton_stage_grounds_a_fractional_pose() {
        let dir = tempfile::tempdir().expect("tempdir");
        let seed = 1;
        let (mut session, mut demo) = run_fresh_combat_leg_until_skeleton(
            seed,
            dir.path().join("combat-skeleton-fractional.mcvx"),
        );
        assert_eq!(demo.stage, CombatStage::Skeleton);
        assert!(!demo.failed, "unexpected early abort: {:?}", demo.digest);

        let grounded = combat_grounded_feet_y(&session, session.player.position)
            .expect("the fixture grounds the player on generated terrain");
        session.player.position.y = grounded + 1.8;
        session.player.velocity = Vec3::new(0.0, -6.0, 0.0);
        session.player.on_ground = false;
        session.sync_camera();

        let aborted = combat_skeleton_stage(&mut demo, &mut session);
        assert!(!aborted, "unexpected abort: {:?}", demo.digest);
        assert!(!demo.failed, "unexpected abort: {:?}", demo.digest);
        assert_eq!(demo.stage, CombatStage::Creative);
        assert_eq!(demo.skeleton_fired, 1);
        assert!(demo.skeleton_bow);
        assert!(demo.skeleton_respawn);
        assert_eq!(session.player.position.y, grounded);
        assert_eq!(
            demo.skeleton_digest.as_deref(),
            Some(
                "combat_skeleton: seed=1 fired=1 player_hits=1 damage=2 cause=skeleton_arrow arc=true killed=1 bones=1 arrows=2 bow=true respawn=spawn ok=true"
            )
        );
    }

    /// Pre-fix a drifted yaw rotates the 16-ray spot lattice off the only three
    /// rare-bow-passing cells: `-0.851398408` yields zero candidates and the
    /// stage aborts with `observed=spot` 5/5. The stage must pin the canonical
    /// yaw/pitch before the scan and restore them for the Save witness.
    #[test]
    fn combat_skeleton_stage_pins_a_drifted_yaw() {
        let dir = tempfile::tempdir().expect("tempdir");
        let seed = 1;
        let (mut session, mut demo) =
            run_fresh_combat_leg_until_skeleton(seed, dir.path().join("combat-skeleton-yaw.mcvx"));
        assert_eq!(demo.stage, CombatStage::Skeleton);
        assert!(!demo.failed, "unexpected early abort: {:?}", demo.digest);

        session.player.yaw = -0.851_398_4;
        session.player.pitch = 0.4;
        session.sync_camera();

        let aborted = combat_skeleton_stage(&mut demo, &mut session);
        assert!(!aborted, "unexpected abort: {:?}", demo.digest);
        assert!(!demo.failed, "unexpected abort: {:?}", demo.digest);
        assert_eq!(demo.stage, CombatStage::Creative);
        assert!(demo.skeleton_bow);
        assert_eq!(
            demo.skeleton_digest.as_deref(),
            Some(
                "combat_skeleton: seed=1 fired=1 player_hits=1 damage=2 cause=skeleton_arrow arc=true killed=1 bones=1 arrows=2 bow=true respawn=spawn ok=true"
            )
        );
        assert_eq!(session.player.yaw, -std::f32::consts::FRAC_PI_4);
        assert_eq!(session.player.pitch, -0.25);
    }

    /// The fresh leg writes the v9 save through the production save site, and
    /// the file itself carries the two surviving hostile records plus the earned
    /// inventory. The file length and the mob-count offset are MEASURED by
    /// running the fresh leg, never computed by hand: they depend on the exact
    /// serialized size of the inventory stacks the demo earns.
    #[test]
    fn combat_demo_fresh_leg_writes_and_verifies_a_v9_save() {
        let dir = tempfile::tempdir().expect("tempdir");
        let seed = 12345;
        let save_path = dir.path().join("combat-fresh-leg.mcvx");
        let (session, demo) = run_fresh_combat_leg(seed, save_path.clone());

        assert_eq!(demo.stage, CombatStage::Done);
        assert_eq!(demo.saved, 2);
        assert_eq!(demo.records, 2);
        let digest = demo.digest.as_deref().expect("success digest");
        assert!(digest.contains("saved=2 records=2"), "{digest}");
        assert!(digest.contains("ok=true"), "{digest}");

        let bytes = std::fs::read(&save_path).expect("read save");
        assert_eq!(
            bytes.len(),
            COMBAT_SAVE_BYTES,
            "measured fresh-leg save length"
        );
        // Locate the mob count by scanning for the exact two-record tail: the
        // Zombie record starts immediately after the u32 count. This cross-check
        // keeps the pinned offset honest if a future stage changes the layout
        // without re-measuring.
        let (positions, _) = combat_quartet(session.player.position, session.player.yaw, seed);
        let mut tail: Vec<u8> = Vec::new();
        for kind in [MobKind::Zombie, MobKind::Skeleton] {
            let index = MobKind::ALL
                .iter()
                .position(|candidate| *candidate == kind)
                .expect("kind index");
            tail.push(kind.tag());
            for c in positions[index].to_array() {
                tail.extend_from_slice(&c.to_le_bytes());
            }
            tail.extend_from_slice(&COMBAT_PINNED_YAW[index].to_le_bytes());
            tail.extend_from_slice(&COMBAT_PINNED_HEALTH[index].to_le_bytes());
        }
        let tail_start = bytes
            .windows(tail.len())
            .position(|window| window == tail.as_slice())
            .expect("two-record mob tail in the save");
        assert_eq!(
            tail_start - 4,
            COMBAT_SAVE_MOB_COUNT_OFFSET,
            "pinned mob-count offset"
        );
        assert_eq!(&bytes[4..8], &9u32.to_le_bytes(), "v9 version word");
        assert_eq!(
            &bytes[COMBAT_SAVE_MOB_COUNT_OFFSET..COMBAT_SAVE_MOB_COUNT_OFFSET + 4],
            &2u32.to_le_bytes(),
            "mob count at the measured offset"
        );
        assert_eq!(
            COMBAT_SAVE_MOB_COUNT_OFFSET + 4 + tail.len() + COMBAT_SAVE_TAIL_BYTES,
            bytes.len(),
            "the mob tail is followed only by the pack-identity, digest, and config tail"
        );

        let loaded = load_world_from_path(&save_path).expect("load save");
        assert_eq!(loaded.mobs.len(), 2);
        for kind in [MobKind::Zombie, MobKind::Skeleton] {
            let index = MobKind::ALL
                .iter()
                .position(|candidate| *candidate == kind)
                .expect("kind index");
            let record = loaded
                .mobs
                .iter()
                .find(|record| record.kind == kind)
                .unwrap_or_else(|| panic!("missing {kind:?} record"));
            assert_eq!(
                record.position,
                positions[index].to_array(),
                "feet {kind:?}"
            );
            assert_eq!(record.yaw, COMBAT_PINNED_YAW[index], "yaw {kind:?}");
            assert_eq!(
                record.health, COMBAT_PINNED_HEALTH[index],
                "health {kind:?}"
            );
        }
    }

    /// The Fight stage proves the hit sequence on the real records, the Drops
    /// stage then kills the two passive records, and the Save stage that follows
    /// writes only the two surviving hostile records at their pinned damaged
    /// health: neither the fight nor the kills may leak into the save.
    #[test]
    fn combat_demo_fight_stage_hits_the_pig_then_the_save_stays_pinned() {
        let dir = tempfile::tempdir().expect("tempdir");
        let seed = 12345;
        let save_path = dir.path().join("combat-fight.mcvx");
        let mut session = WorldSession::new_session_with_mode(
            seed,
            save_path.clone(),
            DEFAULT_SEASON_LENGTH_DAYS,
            GameMode::Survival,
        );
        let spawn = WorldSession::spawn_position(seed);
        for y in [spawn.y, spawn.y - 4.0] {
            insert_generated_chunk_with_generated_face_neighbors(
                &mut session,
                IVec3::new(
                    spawn.x.floor() as i32,
                    y.floor() as i32,
                    spawn.z.floor() as i32,
                ),
            );
        }

        let mut demo = CombatDemo::new(seed, true, None);
        assert!(!combat_demo_step(&mut demo, &mut session), "settle");
        assert_eq!(demo.stage, CombatStage::Ambient, "the spawn gate settles");
        // This test pins Walk/Fight/Drops/Save; the Ambient proof has its own
        // dedicated test, and the 7-chunk demo fixture has no light grids, so
        // it could never satisfy `column_ready`.
        demo.stage = CombatStage::Spawn;
        assert!(!combat_demo_step(&mut demo, &mut session), "spawn");
        assert_eq!(demo.stage, CombatStage::Walk);
        for pos in demo.spawn_positions {
            insert_generated_chunk_with_generated_face_neighbors(
                &mut session,
                IVec3::new(
                    pos.x.floor() as i32,
                    pos.y.floor() as i32,
                    pos.z.floor() as i32,
                ),
            );
        }

        // Drive the Fight stage directly (in production it runs in the same
        // step as the Walk verdict) so the pig's post-fight state is
        // observable before the Drops stage kills it.
        demo.stage = CombatStage::Fight;
        assert!(
            !combat_fight_stage(&mut demo, &mut session),
            "the fight advances to Drops instead of ending the run"
        );
        assert_eq!(demo.stage, CombatStage::Drops);
        assert!(!demo.failed, "unexpected fight abort: {:?}", demo.digest);
        assert_eq!(demo.melee_hits, 2);
        assert_eq!(demo.melee_damage, SWORD_DAMAGE_WOOD);
        assert_eq!(demo.melee_blocked, 1);

        // Two 4-damage hits from 10 health: the i-frame window refused the
        // re-hit, so exactly one hit landed per window and the fight never kills
        // anything — the Drops stage owns death.
        let camera = session.camera.position;
        let pig = &session.mobs()[0];
        assert_eq!(pig.kind, MobKind::Pig);
        assert_eq!(pig.health, 2, "10 -> 6 -> 2, two hits of 4 damage");
        assert!(pig.hurt > 0.0, "the last hit armed the hurt flash");
        assert!(pig.hurt_iframe > 0.0, "the last hit re-armed i-frames");
        assert_eq!(pig.death, 0.0, "the fight must not start a collapse");
        let knockback = Vec3::new(pig.knockback.x, 0.0, pig.knockback.z);
        let away = Vec3::new(pig.position.x - camera.x, 0.0, pig.position.z - camera.z);
        assert!(
            knockback.length_squared() > 0.0,
            "the hit left a knockback impulse"
        );
        assert!(
            knockback.dot(away) > 0.0,
            "knockback must point away from the attacker"
        );

        // The Drops stage kills the Pig and the Cow and delivers their drops.
        assert!(
            !combat_demo_step(&mut demo, &mut session),
            "the drops stage advances to Hostile"
        );
        assert_eq!(demo.stage, CombatStage::Hostile);
        assert!(!demo.failed, "unexpected drops abort: {:?}", demo.digest);
        assert_eq!(demo.killed, 2);
        assert_eq!(demo.drops, 5, "pig 2 units + cow 3 units");
        assert_eq!(demo.drops_lost, 0);
        assert_eq!(session.mobs().len(), 2, "both passive records were reaped");

        // The hostile proof has its own dedicated test, and this fixture has no
        // lit plain; skip the stage so the pinned save witness is produced by
        // the same Save stage as before.
        demo.stage = CombatStage::Save;

        // The immediately following Save stage pins the two survivors and
        // writes the damaged-health witness the reload leg asserts.
        assert!(
            combat_demo_step(&mut demo, &mut session),
            "the save stage ends the fresh leg"
        );
        assert_eq!(demo.stage, CombatStage::Done);
        assert_eq!(demo.saved, 2);
        assert_eq!(demo.records, 2);
        let digest = demo.digest.as_deref().expect("success digest");
        assert!(
            digest.contains("melee_hits=2 melee_damage=4 melee_blocked=1 killed=2 drops=5"),
            "{digest}"
        );

        let loaded = load_world_from_path(&save_path).expect("load save");
        assert_eq!(loaded.mobs.len(), 2);
        assert!(
            loaded
                .mobs
                .iter()
                .all(|record| matches!(record.kind, MobKind::Zombie | MobKind::Skeleton)),
            "only the two hostile records may survive: {:?}",
            loaded.mobs.iter().map(|r| r.kind).collect::<Vec<_>>()
        );
        for kind in [MobKind::Zombie, MobKind::Skeleton] {
            let index = MobKind::ALL
                .iter()
                .position(|candidate| *candidate == kind)
                .expect("kind index");
            let record = loaded
                .mobs
                .iter()
                .find(|record| record.kind == kind)
                .unwrap_or_else(|| panic!("missing {kind:?} record"));
            assert_eq!(
                record.health, COMBAT_PINNED_HEALTH[index],
                "the fight and drops must not leak into the save ({kind:?})"
            );
            assert_eq!(record.yaw, COMBAT_PINNED_YAW[index], "yaw {kind:?}");
        }
    }

    /// The Drops stage alone: a hit makes the Pig flee away, a lethal hit
    /// collapses it and the reaper removes the record, and both kills deliver
    /// raw meat and leather into the real inventory. Removing flee, the collapse
    /// timer, the reaper, or the drop grant aborts the stage or leaves the
    /// inventory short, so this test fails for any of them.
    #[test]
    fn combat_demo_drops_stage_proves_flee_collapse_reap_and_drops() {
        let dir = tempfile::tempdir().expect("tempdir");
        let seed = 12345;
        let save_path = dir.path().join("combat-drops.mcvx");
        let mut session = WorldSession::new_session_with_mode(
            seed,
            save_path.clone(),
            DEFAULT_SEASON_LENGTH_DAYS,
            GameMode::Survival,
        );
        let spawn = WorldSession::spawn_position(seed);
        for y in [spawn.y, spawn.y - 4.0] {
            insert_generated_chunk_with_generated_face_neighbors(
                &mut session,
                IVec3::new(
                    spawn.x.floor() as i32,
                    y.floor() as i32,
                    spawn.z.floor() as i32,
                ),
            );
        }

        let mut demo = CombatDemo::new(seed, true, None);
        assert!(!combat_demo_step(&mut demo, &mut session), "settle");
        assert_eq!(demo.stage, CombatStage::Ambient, "the spawn gate settles");
        // This test pins Walk/Fight/Drops/Save; the Ambient proof has its own
        // dedicated test, and the 7-chunk demo fixture has no light grids, so
        // it could never satisfy `column_ready`.
        demo.stage = CombatStage::Spawn;
        assert!(!combat_demo_step(&mut demo, &mut session), "spawn");
        assert_eq!(demo.stage, CombatStage::Walk);
        for pos in demo.spawn_positions {
            insert_generated_chunk_with_generated_face_neighbors(
                &mut session,
                IVec3::new(
                    pos.x.floor() as i32,
                    pos.y.floor() as i32,
                    pos.z.floor() as i32,
                ),
            );
        }

        // The Walk verdict runs Fight in the same step, which hands over to
        // Drops. Stopping there proves the Drops stage against the real quartet.
        let mut updates = 0u32;
        while demo.stage == CombatStage::Walk && updates < 600 {
            updates += 1;
            session.tick_mobs(0.05, 1.0);
            combat_demo_step(&mut demo, &mut session);
        }
        assert_eq!(
            demo.stage,
            CombatStage::Drops,
            "the walk verdict handed over to drops: {:?}",
            demo.digest
        );
        assert!(!demo.failed, "unexpected abort: {:?}", demo.digest);
        assert_eq!(
            session.mobs().len(),
            4,
            "the quartet starts the drops stage"
        );

        assert!(
            !combat_drops_stage(&mut demo, &mut session),
            "the drops stage advances to Hostile"
        );
        assert_eq!(demo.stage, CombatStage::Hostile);
        assert!(!demo.failed, "unexpected drops abort: {:?}", demo.digest);
        assert_eq!(demo.killed, 2);
        assert_eq!(demo.drops, 5);
        assert_eq!(demo.drops_lost, 0);
        // The hostile proof has its own dedicated test; hand straight to Save so
        // this test still ends on the pinned save witness.
        demo.stage = CombatStage::Save;

        // Both passive records were reaped; only the hostiles remain.
        assert_eq!(session.mobs().len(), 2);
        assert!(
            session
                .mobs()
                .iter()
                .all(|mob| matches!(mob.kind, MobKind::Zombie | MobKind::Skeleton)),
            "dead passive records must be reaped: {:?}",
            session
                .mobs()
                .iter()
                .map(|mob| mob.kind)
                .collect::<Vec<_>>()
        );

        // The drops landed in the real 36-slot inventory next to the earned
        // sword.
        let sword_id = ItemId::Tool {
            kind: ToolKind::Sword,
            tier: ToolTier::Wood,
        };
        assert_eq!(combat_inventory_units(&session, sword_id), 1);
        assert_eq!(
            combat_inventory_units(&session, ItemId::Material(Material::RawPorkchop)),
            1
        );
        assert_eq!(
            combat_inventory_units(&session, ItemId::Material(Material::RawBeef)),
            1
        );
        assert_eq!(
            combat_inventory_units(&session, ItemId::Material(Material::Leather)),
            3,
            "pig 1 + cow 2 leather units"
        );

        // The success digest reports the latched drop verdict.
        assert!(
            combat_demo_step(&mut demo, &mut session),
            "the save stage ends the fresh leg"
        );
        assert_eq!(demo.stage, CombatStage::Done);
        let digest = demo.digest.as_deref().expect("success digest");
        assert!(
            digest.contains("killed=2 drops=5 drops_lost=0 saved=2 records=2 ok=true"),
            "{digest}"
        );
    }

    /// The reload leg is a second invocation against the same save path: a
    /// loaded session starts at Restore, and one step proves the pinned kinds,
    /// positions, yaw, and damaged health through the real startup path.
    #[test]
    fn combat_demo_reload_leg_restores_the_pinned_records() {
        let dir = tempfile::tempdir().expect("tempdir");
        let seed = 12345;
        let save_path = dir.path().join("combat-reload.mcvx");
        let _ = run_fresh_combat_leg(seed, save_path.clone());

        // Relaunch exactly as the binary does: `--save P --demo-combat`, no
        // `--new`, so the startup path loads the fresh leg's save.
        let cli = CliConfig::parse_args([
            "--save",
            save_path.to_str().expect("utf8 path"),
            "--demo-combat",
        ]);
        let session = startup_session(&cli);
        let mut app = GameApp::new(cli, session);
        assert_eq!(app.lifecycle.screen(), LifecycleScreen::Playing);
        let demo = app.combat_demo.as_ref().expect("seam armed");
        assert!(!demo.fresh, "a loaded session is never a fresh spawn");
        assert_eq!(demo.stage, CombatStage::Restore);

        app.step_scripted_demos();
        let digest = app
            .combat_demo
            .as_ref()
            .and_then(|demo| demo.digest.clone())
            .expect("restore digest");
        assert_eq!(
            digest,
            "combat_demo: seed=12345 stage=restored mobs=2 health=11/14 yaw=true positions=true items=8 ok=true"
        );
        assert!(!app.exit_failure);
    }

    /// Deadline and walk-timeout runs latch self-describing aborts (and the
    /// first outcome wins), so a stalled harness still gets a verdict digest.
    #[test]
    fn combat_demo_deadline_and_walk_aborts_are_self_describing() {
        let dir = tempfile::tempdir().expect("tempdir");
        let mut session = WorldSession::new_session_with_mode(
            12345,
            dir.path().join("combat-abort.mcvx"),
            DEFAULT_SEASON_LENGTH_DAYS,
            GameMode::Survival,
        );
        let past = Instant::now() - Duration::from_secs(1);
        let mut demo = CombatDemo::new(12345, true, Some(past));
        assert!(combat_demo_step(&mut demo, &mut session));
        assert!(demo.failed, "a deadline is a failed run");
        let digest = demo.digest.clone().expect("deadline digest latched");
        assert!(
            digest.starts_with("combat_demo: seed=12345 stage=deadline "),
            "{digest}"
        );
        assert!(digest.contains("ok=false"), "{digest}");
        demo.abort("walk", "synthetic_second_abort");
        assert_eq!(
            demo.digest.as_deref(),
            Some(digest.as_str()),
            "the first outcome wins"
        );

        // Walk timeout: a spawned quartet that is never ticked stays unwalked,
        // and the 600th observation aborts instead of waiting forever.
        let spawn = WorldSession::spawn_position(12345);
        insert_generated_chunk_with_generated_face_neighbors(
            &mut session,
            IVec3::new(
                spawn.x.floor() as i32,
                spawn.y.floor() as i32,
                spawn.z.floor() as i32,
            ),
        );
        insert_generated_chunk_with_generated_face_neighbors(
            &mut session,
            IVec3::new(
                spawn.x.floor() as i32,
                (spawn.y - 4.0).floor() as i32,
                spawn.z.floor() as i32,
            ),
        );
        let mut demo = CombatDemo::new(12345, true, None);
        assert!(
            !combat_demo_step(&mut demo, &mut session),
            "stays in Settle"
        );
        assert_eq!(demo.stage, CombatStage::Ambient, "settle hands to ambient");
        // This test pins the Walk timeout; the 7-chunk fixture has no light
        // grids, so the Ambient proof lives in its own dedicated test.
        demo.stage = CombatStage::Spawn;
        assert!(
            !combat_demo_step(&mut demo, &mut session),
            "spawns into Walk"
        );
        assert_eq!(demo.stage, CombatStage::Walk);
        demo.walk_updates = 599;
        assert!(combat_demo_step(&mut demo, &mut session));
        let digest = demo.digest.as_deref().expect("walk abort digest");
        assert!(digest.contains("stage=walk"), "{digest}");
        assert!(digest.contains("walked=0"), "{digest}");
        assert!(digest.contains("ok=false"), "{digest}");
        assert!(demo.failed);
    }

    /// A main-storage item moves into a full hotbar by freeing one slot into an
    /// empty main slot, and the cursor must end empty.
    #[test]
    fn content_demo_ensure_selected_moves_a_main_item_into_a_full_hotbar() {
        let mut slots: [Option<Item>; INVENTORY_SLOTS] = [None; INVENTORY_SLOTS];
        let dirt = Item::new(ItemId::Block(BlockId::Dirt), 1).expect("valid dirt stack");
        for slot in slots.iter_mut().take(HOTBAR_SLOTS) {
            *slot = Some(dirt);
        }
        let hoe_id = ItemId::Tool {
            kind: ToolKind::Hoe,
            tier: ToolTier::Wood,
        };
        slots[HOTBAR_SLOTS + 2] = Some(Item::new(hoe_id, 1).expect("valid hoe"));
        let inventory = Inventory::from_parts(slots, None);
        let mut player = Player::with_inventory(
            Vec3::ZERO,
            inventory,
            CraftingGrid::new(GridKind::Player),
            CraftingGrid::new(GridKind::Table),
        );

        assert!(content_demo_ensure_selected(&mut player, hoe_id));
        assert_eq!(player.selected_slot(), 0);
        assert_eq!(
            player.inventory().hotbar(0).map(|item| item.id()),
            Some(hoe_id)
        );
        assert_eq!(
            player.inventory().slot(HOTBAR_SLOTS).map(|item| item.id()),
            Some(ItemId::Block(BlockId::Dirt)),
            "the displaced hotbar stack lands in the first empty main slot"
        );
        assert!(
            player.inventory().cursor().is_none(),
            "the cursor ends empty"
        );
    }

    #[test]
    fn saved_time_of_day_resumes_exactly_across_a_save_and_relaunch() {
        let dir = tempfile::tempdir().expect("tempdir");
        let save_path = dir.path().join("time.mcvx");
        let mut app = playing_app(dir.path(), "time.mcvx");
        app.session.clock = opencraft::world::daycycle::GameClock::from_time(17_432);
        assert_ne!(17_432, daycycle::DEFAULT_TIME_OF_DAY);

        // The real save path writes `session.clock.time_of_day`.
        save_current_world(&mut app.session).expect("save succeeds");

        // Session-level relaunch: load the file, round-trip it through the
        // bytes API, and rebuild a session the way startup does.
        let loaded = load_world_from_path(&save_path).expect("load succeeds");
        let mut bytes = Vec::new();
        opencraft::world::persistence::save_world_to_bytes(&mut bytes, &loaded)
            .expect("re-save to bytes");
        let decoded = opencraft::world::persistence::load_world_from_bytes(&bytes)
            .expect("bytes load succeeds");
        let relaunched = WorldSession::session_from_save(decoded, save_path.clone());

        assert_eq!(relaunched.clock.time_of_day, 17_432);
        assert_eq!(relaunched.save_path, save_path);
    }

    #[test]
    fn accelerated_demo_cycle_saves_and_reloads_day_index_one() {
        let dir = tempfile::tempdir().expect("tempdir");
        let save_path = dir.path().join("calendar.mcvx");
        let mut app = playing_app(dir.path(), "calendar.mcvx");
        app.time_scale = 60.0;
        app.session.season_length_days = 4;
        let start = Instant::now();

        // The same frame loop the bounded demo runs: one full cycle at 60x
        // takes 20 simulated seconds (24,000 ticks / 1,200 per second).
        tick_app_clock(&mut app, start);
        assert!(!observe_demo_cycle(
            &mut app.demo_cycle,
            app.time_scale,
            app.demo_days,
            true,
            app.session.clock.time_of_day
        ));
        let mut finished = false;
        let mut frames = 0;
        while frames < 25 && !finished {
            frames += 1;
            tick_app_clock(&mut app, start + Duration::from_secs(frames));
            finished = observe_demo_cycle(
                &mut app.demo_cycle,
                app.time_scale,
                app.demo_days,
                true,
                app.session.clock.time_of_day,
            );
        }
        assert!(finished, "the accelerated demo must complete one cycle");

        // From the default noon start, one full cycle returns the clock to
        // noon and crosses dawn (tick 0) exactly once: day index 1.
        assert_eq!(app.session.clock.time_of_day, daycycle::DEFAULT_TIME_OF_DAY);
        assert_eq!(app.session.clock.day_index, 1);

        // The demo's shutdown save persists the calendar tail; the reload
        // restores both fields byte-exactly.
        save_current_world(&mut app.session).expect("demo shutdown save succeeds");
        let loaded = load_world_from_path(&save_path).expect("load succeeds");
        assert_eq!(loaded.day_index, 1);
        assert_eq!(loaded.season_length_days, 4);
        let relaunched = WorldSession::session_from_save(loaded, save_path.clone());
        assert_eq!(relaunched.clock.day_index, 1);
        assert_eq!(relaunched.season_length_days, 4);
    }

    /// S06-T05: the demo seam itself. One accelerated session with
    /// `--demo-days 4` spans the whole seed-1 year (Rain -> Clear -> Rain ->
    /// Snowfall), proving the multi-cycle budget delivers what the slice demo
    /// claims: warm-season rain and winter snowfall in a single run, with the
    /// default one-cycle bound untouched (see
    /// `accelerated_demo_cycle_saves_and_reloads_day_index_one`).
    #[test]
    fn four_day_demo_spans_the_seed_one_year_in_one_accelerated_session() {
        let dir = tempfile::tempdir().expect("tempdir");
        let save_path = dir.path().join("year.mcvx");
        let cli = CliConfig::parse_args([
            "--new",
            "--save",
            save_path.to_str().expect("utf8 path"),
            "--demo-days",
            "4",
            "--time-scale",
            "60",
        ]);
        // Seed 1 at one-day seasons is the slice's demo calendar.
        let session = WorldSession::new_session(1, save_path.clone(), 1);
        let mut app = GameApp::new(cli, session);
        assert_eq!(app.demo_days, 4, "the flag reaches the app");
        assert_eq!(app.time_scale, 60.0);
        let start = Instant::now();

        // 4 days x 20 simulated seconds at 60x = 80 real seconds. The season
        // packet must be re-derived per frame from the persisted calendar, so
        // sampling it after each day boundary is the honest presentation path.
        tick_app_clock(&mut app, start);
        assert!(!observe_demo_cycle(
            &mut app.demo_cycle,
            app.time_scale,
            app.demo_days,
            true,
            app.session.clock.time_of_day
        ));

        let expected = [
            Weather::Rain,
            Weather::Clear,
            Weather::Rain,
            Weather::Snowfall,
        ];
        let mut seen = vec![(app.session.clock.day_index, session_weather(&app.session))];
        let mut finished = false;
        let mut frames = 0;
        while frames < 85 && !finished {
            frames += 1;
            tick_app_clock(&mut app, start + Duration::from_secs(frames));
            finished = observe_demo_cycle(
                &mut app.demo_cycle,
                app.time_scale,
                app.demo_days,
                true,
                app.session.clock.time_of_day,
            );
            let sample = (app.session.clock.day_index, session_weather(&app.session));
            if seen.last() != Some(&sample) {
                seen.push(sample);
            }
            // The watch must not latch before the fourth cycle completes.
            if frames < 80 {
                assert!(
                    !finished,
                    "a 4-day demo must not finish after {frames} simulated seconds"
                );
            }
        }

        assert!(finished, "the 4-day demo must complete");
        assert_eq!(frames, 80, "4 days x 20 simulated seconds at 60x");
        assert_eq!(app.session.clock.day_index, 4);
        assert_eq!(app.session.clock.time_of_day, daycycle::DEFAULT_TIME_OF_DAY);

        // Each day of the seed-1 year was presented, in order, exactly once
        // (day 4 wraps back to Spring's Rain, so it closes the pattern).
        let days: Vec<(u32, Weather)> = seen.clone();
        assert_eq!(
            days,
            vec![
                (0, expected[0]),
                (1, expected[1]),
                (2, expected[2]),
                (3, expected[3]),
                (4, expected[0]),
            ],
            "one session must present the whole seed-1 year"
        );

        // The shutdown save persists the four-day calendar tail, so an
        // accelerated year is resumable like any other session.
        save_current_world(&mut app.session).expect("demo shutdown save succeeds");
        let loaded = load_world_from_path(&save_path).expect("load succeeds");
        assert_eq!(loaded.day_index, 4);
        assert_eq!(loaded.season_length_days, 1);
    }

    /// Accelerated day-boundary clock proof (M007/S05): a real `GameApp`
    /// session whose `GameClock` crosses `DAY_BOUNDARY_TICK` at the
    /// `--time-scale` seam derives Winter through `WorldSession::season`, the
    /// exact method the Playing frame loop calls. The resident worldgen that
    /// follows the season is proven separately in the lib-side
    /// `world::manager` day-boundary test, where the global rayon pool can be
    /// serialised and drained without starving sibling bin tests.
    #[test]
    fn accelerated_day_boundary_flips_the_session_season_to_winter() {
        use opencraft::world::season::FIRST_WINTER_DAY;

        let dir = tempfile::tempdir().expect("tempdir");
        let save_path = dir.path().join("day-boundary.mcvx");
        let cli =
            CliConfig::parse_args(["--new", "--save", save_path.to_str().expect("utf8 path")]);
        // Seed 1 starts in Spring, so day 3 is Winter at one-day seasons.
        let mut app = GameApp::new(cli, WorldSession::new_session(1, save_path, 1));
        assert_eq!(app.lifecycle.screen(), LifecycleScreen::Playing);
        app.time_scale = 60.0;

        // Day 2 is Autumn for seed 1. Start just before the day boundary so a
        // single accelerated frame crosses it.
        app.session.clock =
            opencraft::world::daycycle::GameClock::from_day_and_time(2, daycycle::DAY_TICKS - 10);
        assert_eq!(app.session.season(), Season::Autumn);

        let start = Instant::now();
        // Arm the clock marker; the next accelerated frame advances 1,200 ticks
        // (1 real second at 60x), crossing DAY_BOUNDARY_TICK.
        tick_app_clock(&mut app, start);
        tick_app_clock(&mut app, start + Duration::from_secs(1));

        assert_eq!(
            app.session.clock.day_index, FIRST_WINTER_DAY,
            "test premise: seed 1 at one-day seasons reaches Winter on day 3"
        );
        assert_eq!(
            app.session.clock.time_of_day,
            (daycycle::DAY_TICKS - 10 + 1_200) % daycycle::DAY_TICKS
        );
        assert_eq!(
            app.session.season(),
            Season::Winter,
            "the real clock crossing must feed Winter into the session's season derivation"
        );
    }

    #[test]
    fn startup_session_honors_season_length_on_the_fresh_world_branch_only() {
        let dir = tempfile::tempdir().expect("tempdir");
        let fresh_path = dir.path().join("fresh.mcvx");
        let path_str = fresh_path.to_str().expect("utf8 path");

        // Fresh branch: the CLI seam overrides the default season length.
        let cli = CliConfig::parse_args(["--new", "--save", path_str, "--season-length", "4"]);
        let session = startup_session(&cli);
        assert_eq!(session.season_length_days, 4);
        assert_eq!(session.clock.day_index, 0, "fresh worlds start on day 0");

        // ...and the default applies when the flag is absent.
        let bare_fresh = CliConfig::parse_args(["--new", "--save", path_str]);
        assert_eq!(
            startup_session(&bare_fresh).season_length_days,
            DEFAULT_SEASON_LENGTH_DAYS
        );

        // Load branch: a persisted calendar wins over the launch flag.
        let mut data = sample_save(42);
        data.day_index = 3;
        data.season_length_days = 8;
        save_world_to_path(&fresh_path, &data).expect("write calendar save");
        let load_cli = CliConfig::parse_args(["--save", path_str, "--season-length", "2"]);
        let loaded = startup_session(&load_cli);
        assert_eq!(loaded.clock.day_index, 3, "persisted day index wins");
        assert_eq!(
            loaded.season_length_days, 8,
            "a load ignores --season-length"
        );
    }

    #[test]
    fn startup_session_applies_cli_mode_to_fresh_worlds_only() {
        let dir = tempfile::tempdir().expect("tempdir");
        let fresh_path = dir.path().join("fresh-mode.mcvx");
        let path_str = fresh_path.to_str().expect("utf8 path");

        // Fresh + --survival: Survival rules, full vitals, walking.
        let cli = CliConfig::parse_args(["--new", "--save", path_str, "--survival"]);
        let session = startup_session(&cli);
        assert_eq!(session.save_mode, GameMode::Survival);
        assert_eq!(session.player.mode(), GameMode::Survival);
        assert!(!session.player.can_fly());
        assert_eq!(session.player.survival, SurvivalState::full());

        // Fresh default and explicit --creative both keep the Creative /
        // flying default every pre-M008 launch had.
        for args in [
            vec!["--new", "--save", path_str],
            vec!["--new", "--save", path_str, "--creative"],
        ] {
            let session = startup_session(&CliConfig::parse_args(args.iter().copied()));
            assert_eq!(session.save_mode, GameMode::Creative, "args: {args:?}");
            assert_eq!(session.player.mode(), GameMode::Creative);
            assert!(session.player.can_fly(), "args: {args:?}");
        }

        // Loaded saves ignore the flag: the persisted mode is authoritative,
        // in both directions.
        let mut survival = sample_save(11);
        survival.mode = GameMode::Survival;
        survival.player.fly_mode = false;
        let survival_path = dir.path().join("persisted-survival.mcvx");
        save_world_to_path(&survival_path, &survival).expect("write survival save");
        let loaded = startup_session(&CliConfig::parse_args([
            "--save",
            survival_path.to_str().unwrap(),
            "--creative",
        ]));
        assert_eq!(loaded.save_mode, GameMode::Survival);
        assert_eq!(loaded.player.mode(), GameMode::Survival);
        assert!(!loaded.player.can_fly());

        let creative_path = dir.path().join("persisted-creative.mcvx");
        save_world_to_path(&creative_path, &sample_save(12)).expect("write creative save");
        let loaded = startup_session(&CliConfig::parse_args([
            "--save",
            creative_path.to_str().unwrap(),
            "--survival",
        ]));
        assert_eq!(loaded.save_mode, GameMode::Creative);
        assert_eq!(loaded.player.mode(), GameMode::Creative);
        assert!(loaded.player.can_fly());
    }

    /// A headless GameApp for seam tests: no window/GPU, a tempdir catalog,
    /// and the given screen entered through the real `enter_screen` path
    /// (LoadGame entry refreshes rows from the tempdir catalog).
    fn app_at_screen(saves_dir: &Path, screen: LifecycleScreen) -> GameApp {
        let cli = CliConfig::parse_args(Vec::<String>::new());
        // Injectable paths keep every headless test independent of the crate
        // root's real settings.toml and background save (M012). A missing
        // background is the deterministic demo scene.
        let mut app = GameApp::new_with_paths(
            cli,
            WorldSession::new_session(
                1,
                PathBuf::from("/nonexistent/initial.mcvx"),
                DEFAULT_SEASON_LENGTH_DAYS,
            ),
            Path::new(DEFAULT_SETTINGS_PATH).to_path_buf(),
            saves_dir.join("background/background.mcvx"),
        );
        app.catalog = WorldCatalogFs::new(saves_dir);
        app.enter_screen(screen);
        app
    }

    #[test]
    fn game_app_in_test_builds_owns_a_silent_audio_engine() {
        // The suite builds many headless GameApps; the cfg(test) constructor
        // must never open a real device/CPAL stream. Playback itself is
        // unreachable from the test-driven free helpers (the wiring rule),
        // so a silent engine is the complete test-side contract.
        let dir = tempfile::tempdir().expect("tempdir");
        let app = app_at_screen(dir.path(), LifecycleScreen::MainMenu);
        assert!(
            app.audio.is_silent(),
            "test GameApps must use AudioEngine::disabled()"
        );
        // The real play surface is still callable and a no-op at every
        // volume boundary (0 mutes, 100 normal, >100 clamps internally).
        for slot in SoundSlot::ALL {
            app.audio.play(slot, 0);
            app.audio.play(slot, app.settings.volume);
            app.audio.play(slot, 255);
        }
    }

    #[test]
    fn fresh_game_app_has_a_fixed_seed_vista_at_the_settings_render_distance() {
        let app = app_at_screen(Path::new("/nonexistent/saves"), LifecycleScreen::MainMenu);
        assert_eq!(app.background.world.seed(), vista::VISTA_SEED);
        assert_eq!(
            app.background.world.render_distance(),
            app.settings.render_distance,
            "the background follows the settings-driven render distance"
        );
        // The background is its own world, not a hidden alias of the session.
        assert_ne!(
            app.background.world.seed(),
            app.session.world.seed(),
            "background and session are distinct, independently seeded worlds"
        );
    }

    /// Every `.mcvx` file below `root`, recursively: proves a launch wrote no
    /// playable (or background) save path, not just the one path under test.
    fn mcvx_files_under(root: &Path) -> Vec<PathBuf> {
        fn walk(dir: &Path, out: &mut Vec<PathBuf>) {
            let Ok(entries) = std::fs::read_dir(dir) else {
                return;
            };
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    walk(&path, out);
                } else if path.extension().is_some_and(|ext| ext == "mcvx") {
                    out.push(path);
                }
            }
        }
        let mut out = Vec::new();
        walk(root, &mut out);
        out
    }

    /// A headless GameApp for background-scene tests: tempdir settings and
    /// background paths, bare CLI (main menu), and a fixed session.
    fn app_with_background(saves_dir: &Path) -> GameApp {
        GameApp::new_with_paths(
            CliConfig::parse_args(Vec::<String>::new()),
            WorldSession::new_session(
                1,
                PathBuf::from("/nonexistent/initial.mcvx"),
                DEFAULT_SEASON_LENGTH_DAYS,
            ),
            saves_dir.join("settings.toml"),
            saves_dir.join("background/background.mcvx"),
        )
    }

